from __future__ import annotations

MODEL190_RECEIPT_CSS = r'  @page { size: A4 portrait; margin: 7mm; }\n  * { box-sizing: border-box; }\n  html { background: #eceff3; }\n  body { margin: 0; color: #111; font-family: Arial, Helvetica, sans-serif; font-size: 9px; }\n  .sheet { position: relative; width: 196mm; min-height: 283mm; margin: 8mm auto; padding: 4mm; overflow: hidden; background: #fff; page-break-after: always; }\n  .sheet:last-child { page-break-after: auto; }\n  .watermark { position: absolute; top: 140mm; left: 22mm; z-index: 0; color: rgba(175, 0, 0, .075); font-size: 34px; font-weight: 900; letter-spacing: .2em; transform: rotate(-28deg); white-space: nowrap; }\n  .sheet > *:not(.watermark) { position: relative; z-index: 1; }\n  .official-header { display: grid; grid-template-columns: 21mm 45mm 1fr 24mm; gap: 2mm; height: 27mm; margin-bottom: 3mm; }\n  .ministry-block { display: grid; place-items: center; }\n  .ministry-block img { width: 17mm; height: auto; max-height: 20mm; object-fit: contain; }\n  .agency-block { display: flex; align-items: center; gap: 2mm; padding: 3mm; border-right: 1px solid #777; border-bottom: 1px solid #777; background: #dce4f5; box-shadow: 1.2mm 1.2mm 0 #9b9b9b; }\n  .agency-block strong { display: block; margin-bottom: 3mm; font-size: 13px; font-weight: 500; }\n  .agency-block span { display: block; margin-top: 1mm; font-size: 8px; }\n  .agency-mark { position: relative; width: 10mm; height: 14mm; flex: 0 0 10mm; }\n  .agency-mark i:first-child { position: absolute; left: 0; top: 1mm; width: 0; height: 0; border-top: 6mm solid transparent; border-bottom: 6mm solid transparent; border-right: 7mm solid #30333a; transform: skewX(-10deg); }\n  .agency-mark i:last-child { position: absolute; right: 0; top: 0; width: 0; height: 0; border-top: 7mm solid transparent; border-bottom: 7mm solid transparent; border-left: 7mm solid #858b96; }\n  .title-block { display: grid; align-content: center; gap: 1.5mm; padding: 2.5mm 3mm; border: 1px solid #07599e; background: #0a69b5; color: white; text-align: center; box-shadow: 1.2mm 1.2mm 0 #888; }\n  .title-block strong { font-size: 15px; }\n  .title-block span { font-size: 9px; font-weight: 700; line-height: 1.25; }\n  .title-block b { font-size: 15px; }\n  .model-block { display: grid; grid-template-rows: 8mm 1fr; border: 1px solid #777; background: #dce4f5; text-align: center; box-shadow: 1.2mm 1.2mm 0 #888; }\n  .model-block > span { display: grid; place-items: center; background: #0a69b5; color: white; font-size: 8px; font-weight: 800; }\n  .model-block small { align-self: end; font-size: 8px; }\n  .model-block strong { align-self: start; font-size: 28px; line-height: 1; }\n  .top-grid { display: grid; grid-template-columns: 3fr 2fr; gap: 2mm; }\n  .left-column, .right-column { display: grid; gap: 2mm; align-content: start; }\n  .box { min-width: 0; margin: 0; padding: 3mm 3mm 2.5mm; border: 1px solid #111; background: #dce4f5; }\n  .box legend { padding: 1mm 4mm; border: 1px solid #111; background: #5d91cb; color: white; font-size: 9px; font-weight: 800; }\n  .box label { display: grid; gap: 1mm; margin-top: 2mm; font-size: 7px; }\n  .field { display: block; min-height: 6mm; padding: 1.2mm 1.5mm; border: 0; border-bottom: 1px solid #777; background: white; box-shadow: 1mm 1mm 0 #aaa; font-size: 9px; font-weight: 700; }\n  .field.short { width: 36mm; letter-spacing: .08em; }\n  .label-space { display: grid; place-items: center; height: 22mm; padding: 4mm; border: 1px dashed #666; background: white; text-align: center; }\n  .label-space span { max-width: 90%; font-size: 6.8px; line-height: 1.35; }\n  .declarant-box { min-height: 47mm; }\n  .contact-box { min-height: 24mm; }\n  .dotted-space { height: 20mm; border: 1px dashed #666; background: #fff; }\n  .exercise-box { min-height: 12mm; }\n  .exercise-line { display: flex; align-items: center; justify-content: space-between; gap: 2mm; }\n  .exercise-line b { min-width: 20mm; padding: 2mm; border-bottom: 1px solid #777; background: white; box-shadow: 1mm 1mm 0 #aaa; text-align: center; font-size: 12px; letter-spacing: .2em; }\n  .mode-box { min-height: 22mm; }\n  .mode-box p { margin: 0 0 2mm; font-size: 7px; line-height: 1.25; }\n  .mode-row { display: grid; grid-template-columns: 14mm 1fr 6mm; align-items: center; gap: 1.5mm; margin-top: 1.5mm; }\n  .mode-row i, .declaration-grid i { display: grid; place-items: center; width: 5mm; height: 5mm; border: 0; background: white; box-shadow: 1mm 1mm 0 #aaa; font-style: normal; font-weight: 900; }\n  .mode-row i.checked { color: #111; }\n  .summary-box { min-height: 31mm; margin-top: 2mm; }\n  .summary-row { display: flex; align-items: flex-end; gap: 1.5mm; margin: 1.3mm 0; }\n  .summary-row b { font-size: 8px; white-space: nowrap; }\n  .summary-row .dots { flex: 1; border-bottom: 1px dotted #111; }\n  .summary-row em { display: grid; place-items: center; width: 5mm; height: 5mm; background: #5d91cb; color: white; font-style: normal; font-weight: 800; }\n  .summary-row strong { min-width: 30mm; min-height: 6mm; padding: 1.2mm; border-bottom: 1px solid #777; background: white; box-shadow: 1mm 1mm 0 #aaa; text-align: right; font-size: 10px; }\n  .footnote { margin: 2mm 0 0; font-size: 6.3px; line-height: 1.25; }\n  .declaration-box { min-height: 22mm; margin-top: 2mm; }\n  .declaration-box > p { margin: 0 0 3mm; font-size: 7px; line-height: 1.35; }\n  .declaration-grid { display: grid; grid-template-columns: 1fr 2fr; gap: 2mm 8mm; align-items: center; }\n  .declaration-grid label { display: flex; align-items: center; justify-content: space-between; gap: 2mm; margin: 0; font-size: 8px; font-weight: 700; }\n  .declaration-grid .identifier { flex: 1; min-width: 55mm; text-align: center; letter-spacing: .12em; }\n  .bottom-grid { display: grid; grid-template-columns: 1.15fr 1fr; gap: 2mm; margin-top: 2mm; }\n  .signature-box, .administration-box { min-height: 49mm; }\n  .signature-space { display: grid; align-content: start; gap: 2mm; height: 22mm; margin: 1.3mm 0; padding: 3mm; background: white; box-shadow: 1mm 1mm 0 #aaa; }\n  .signature-space b { margin-top: 2mm; text-align: center; color: #1e5794; font-size: 12px; }\n  .signature-space small { text-align: center; }\n  .signature-line { flex: 1; min-height: 4mm; margin-left: 2mm; border-bottom: 1px solid #777; font-size: 8px; font-weight: 700; }\n  .signature-box > label:last-child, .signature-box > label:nth-last-child(2) { display: flex; align-items: flex-end; }\n  .administration-box { background: #dce4f5; }\n  .admin-stamp { margin-bottom: 3mm; padding: 2mm; border: 2px solid #a40000; color: #a40000; text-align: center; font-weight: 900; letter-spacing: .08em; }\n  .admin-data { display: grid; grid-template-columns: 33mm 1fr; gap: 1.5mm 2mm; margin: 0; padding: 3mm; background: white; box-shadow: 1mm 1mm 0 #aaa; }\n  .admin-data dt { color: #555; font-weight: 700; }\n  .admin-data dd { min-width: 0; margin: 0; font-weight: 800; overflow-wrap: anywhere; }\n  .admin-data .hash { font-family: monospace; font-size: 5.5px; }\n  footer { display: flex; justify-content: space-between; align-items: end; gap: 4mm; margin-top: 2mm; padding-top: 1mm; border-bottom: 1px solid #333; font-size: 7px; }\n  footer b { font-size: 9px; }\n  @media print {\n    html, body { background: white; }\n    .sheet { width: auto; min-height: 283mm; margin: 0; padding: 2mm; box-shadow: none; }\n  }'
